  let isGlobalesEvaluated = false;
  let isGlobalesAnimating = false;
  let isGlobalesHoverEnabled = false;
  let currentGlobalesView = 'balanza'; // 'balanza' | 'choque'
  let currentChoqueSalario = 25000;
  let currentChoqueRegimen = 'imss';
