  // ==========================================================================
  // RENDERIZADO: REFERENCIAS APA 7 NUMERADAS CON FILTROS
  // ==========================================================================
  /* Las categorias y sus cuentas salen de la base: el catalogo crece y los
     botones con cifra fija se quedaban atras (decian 27 con 79 fichas). */
  function refsPintarFiltros(filter) {
    const bar = document.getElementById('refsFiltros');
    const total = document.getElementById('refsTotal');
    const refs = DB.referencias_legales || [];
    if (total) total.textContent = refs.length + ' fuentes verificadas';
    if (!bar) return;
    const cats = {};
    refs.forEach(r => {
      if (!cats[r.categoria]) cats[r.categoria] = { nombre: r.categoria_nombre, n: 0 };
      cats[r.categoria].n++;
    });
    const orden = Object.keys(cats).sort((a, b) => cats[b].n - cats[a].n);
    const chip = (k, txt) => '<button type="button" class="chip' + (k === filter ? ' on active' : '') + '" data-reff="' + k + '" onclick="window.AuditEngine.renderReferencias(\'' + k + '\')">' + txt + '</button>';
    bar.innerHTML = chip('todas', 'Todas (' + refs.length + ')') +
      orden.map(k => chip(k, pdEsc(cats[k].nombre) + ' (' + cats[k].n + ')')).join('');
  }

  function abrirCatalogoFuentes(refId) {
    cerrarMegaMenus();
    const desglose = document.getElementById('seccionDesgloseModulos');
    if (desglose) { desglose.style.display = 'block'; desglose.classList.add('desglose-abierto'); }
    switchTab('faq');
    switchSubtab('faq', 'faq-referencias');
    const panel = document.querySelector('.subtab-panel[data-parent="faq"][data-subpanel="faq-referencias"]');
    const el = (refId && document.getElementById(refId)) || panel;
    if (!el) return;
    setTimeout(() => {
      el.scrollIntoView({ behavior: 'smooth', block: refId ? 'center' : 'start' });
      if (refId) {
        el.classList.add('ref-row-destacada');
        setTimeout(() => el.classList.remove('ref-row-destacada'), 2600);
      }
    }, 60);
  }

  function renderReferencias(filter = 'todas') {
    const container = document.getElementById('refsListContainer');
    if (!container || !DB.referencias_legales) return;
    refsPintarFiltros(filter);

    let items = DB.referencias_legales;
    // Se ordena por numero de cita para que el catalogo siga la numeracion
    // de las notas al pie, sin depender del orden de insercion en la base.
    items = items.slice().sort((a, b) => (a.num || 0) - (b.num || 0));
    if (filter !== 'todas') {
      items = items.filter(ref => ref.categoria === filter);
    }

    container.innerHTML = items.map(ref => `
      <li class="ref-row-item" id="${ref.id}">
        <div class="ref-num-badge">[${ref.num}]</div>
        <div class="ref-content-body">
          <div class="ref-citation-apa">
            ${ref.cita_apa}
            ${ref.url ? `<br><a href="${ref.url}" target="_blank" rel="noopener noreferrer">↗ Consultar texto oficial en PDF / portal</a>` : ''}
          </div>
          <div class="ref-note">${ref.descripcion}</div>
        </div>
        <div class="ref-tag-pill">${ref.categoria_nombre}</div>
      </li>
    `).join('');

    // Actualizar botones de chips
    document.querySelectorAll('[data-reff]').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.reff === filter);
    });
  }

  /* ======================================================================
     PESTANA 9 - CAPA DE ORIENTACION Y UTILIDADES COMUNES
     Tres funciones conviven en esta pestana y hasta ahora no se distinguian:
     aportar a la plataforma, denunciar ante el Estado y debatir en publico.
     Solo una de las tres tiene efecto juridico. Esta capa lo dice antes de
     que la persona escriba una sola palabra.
     ====================================================================== */

  /* Todo lo que escribe una persona se pinta con innerHTML. Sin escapar, un
     texto con etiquetas se ejecuta como HTML: rompe la maquetacion y abre la
     puerta a inyeccion. Esta funcion es obligatoria en cualquier dato que
     provenga del formulario o del almacenamiento local. */
  function escHtml(v) {
    return String(v == null ? '' : v)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /* Los debates de ejemplo guardan su antiguedad en dias, no una fecha fija:
     asi el foro no envejece mal cuando pasan semanas sin tocar el proyecto. */
  function fechaRelativa(diasAtras) {
    const d = new Date();
    d.setDate(d.getDate() - (parseInt(diasAtras, 10) || 0));
    const fecha = d.toLocaleDateString('es-MX', { day: 'numeric', month: 'short', year: 'numeric' });
    const n = parseInt(diasAtras, 10) || 0;
    let rel;
    if (n <= 0) rel = 'Hoy';
    else if (n === 1) rel = 'Hace 1 día';
    else if (n < 7) rel = 'Hace ' + n + ' días';
    else if (n < 30) rel = 'Hace ' + Math.floor(n / 7) + (Math.floor(n / 7) === 1 ? ' semana' : ' semanas');
    else rel = 'Hace ' + Math.floor(n / 30) + (Math.floor(n / 30) === 1 ? ' mes' : ' meses');
    return { fecha: fecha, relativo: rel };
  }

